import React, { useState, useEffect } from 'react';
import orderService from '../services/orderService';

const ReadyOrders = () => {
  const [orders, setOrders] = useState([]);
  const [fadeOutOrders, setFadeOutOrders] = useState(new Set());
  const [scaleInOrders, setScaleInOrders] = useState(new Set());
  const [glowPulseOrders, setGlowPulseOrders] = useState(new Set());

  useEffect(() => {
    // Initial load
    setOrders(orderService.getReadyOrders());

    // Set up automatic updates every 3 seconds
    const interval = setInterval(() => {
      const previousOrderIds = orders.map(order => order.id);

      // Simulate order updates (status changes, new orders)
      orderService.simulateOrderUpdates();
      const newOrders = orderService.getReadyOrders(); // This filters status='ready' and sorts by ready_at desc
      const currentOrderIds = newOrders.map(order => order.id);

      // Find orders that were removed (status changed from 'ready' to something else)
      const removedOrderIds = orderService.getRemovedOrders(currentOrderIds, previousOrderIds);

      // Find new orders (newly ready orders)
      const newOrderIds = currentOrderIds.filter(id => !previousOrderIds.includes(id));

      // Handle status changes (orders no longer 'ready')
      if (removedOrderIds.length > 0) {
        // Start fade out animation for orders that changed status
        setFadeOutOrders(new Set(removedOrderIds));

        // Remove orders after fade animation completes
        setTimeout(() => {
          setOrders(newOrders);
          setFadeOutOrders(new Set());
        }, 700); // 700ms fade duration to match CSS
      } else {
        // Just update orders if no status changes
        setOrders(newOrders);
      }

      // Handle new ready orders with scale-in animation and green glow pulse
      if (newOrderIds.length > 0) {
        setScaleInOrders(new Set(newOrderIds));
        setGlowPulseOrders(new Set(newOrderIds));

        setTimeout(() => {
          setScaleInOrders(new Set());
        }, 700); // 700ms scale duration to match CSS

        setTimeout(() => {
          setGlowPulseOrders(new Set());
        }, 2000); // 2s glow pulse duration
      }
    }, 3000);

    return () => clearInterval(interval);
  }, [orders]);

  return (
    <div className="w-full h-full flex items-center justify-center">
      {/* Token Grid - 4 columns × 3 rows (12 tokens max) */}
      <div className="grid grid-cols-4 grid-rows-3 gap-6 xl:gap-8 max-w-7xl mx-auto">
        {Array.from({ length: 12 }, (_, index) => {
          const order = orders[index];
          const isFadingOut = order && fadeOutOrders.has(order.id);
          const isScalingIn = order && scaleInOrders.has(order.id);
          const isGlowPulsing = order && glowPulseOrders.has(order.id);

          return (
            <div 
              key={order ? order.id : `empty-${index}`}
              className={`token-card flex items-center justify-center min-h-[200px] transition-all duration-700 ease-in-out ${
                isFadingOut 
                  ? 'fade-out' 
                  : isScalingIn 
                    ? 'scale-in' 
                    : 'normal'
              } ${isGlowPulsing ? 'glow-pulse' : ''}`}
            >
              {order ? (
                <div className="token-number text-9xl font-bold text-white">
                  {order.tokenNumber}
                </div>
              ) : (
                <div className="token-number text-9xl font-bold text-white opacity-30">
                  ---
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default ReadyOrders;
